  ('e486574d-0e7c-5934-99ea-bf2d36278589', 'happy', '/ˈhæpi/', 'adjective', 'feeling pleased and cheerful', 'The children were happy to see their grandmother.', array['glad','cheerful']::text[], array['sad','unhappy']::text[], 'A1', 'daily', null),
  ('ece47d33-93df-5ca3-97ea-40ae645e6c3c', 'tired', '/ˈtaɪəd/', 'adjective', 'needing to rest or sleep', 'I was tired after the long walk home.', array['sleepy','weary']::text[], array['energetic','rested']::text[], 'A1', 'health', null),
  ('eb0f9d5d-46b5-51f7-af31-7c713f822da9', 'hungry', '/ˈhʌŋɡri/', 'adjective', 'wanting or needing food', 'We were hungry, so we stopped for lunch.', array['starving']::text[], array['full']::text[], 'A1', 'health', null),
  ('a92f3cfc-f82f-5b01-8f87-dde2c27d662a', 'buy', '/baɪ/', 'verb', 'to get something by paying money for it', 'I need to buy some bread on the way home.', array['purchase']::text[], array['sell']::text[], 'A1', 'daily', null),
  ('85773117-0ff9-5758-819f-b2bdc70a822c', 'ticket', '/ˈtɪkɪt/', 'noun', 'a paper or digital pass that shows you have paid to travel or to enter a place', 'She showed her ticket to the guard at the station.', array['pass']::text[], array[]::text[], 'A1', 'travel', null),
  ('6b0cdb60-4ca6-5144-b6d4-643b90f0aab3', 'teacher', '/ˈtiːtʃə/', 'noun', 'a person whose job is to help people learn', 'Our teacher explained the lesson very clearly.', array['instructor','tutor']::text[], array[]::text[], 'A1', 'education', null),
  ('deb03d86-b506-531d-8a05-107d73ca96ee', 'cheap', '/tʃiːp/', 'adjective', 'costing little money', 'The market sells cheap fruit and vegetables.', array['inexpensive','affordable']::text[], array['expensive','costly']::text[], 'A1', 'daily', null),
  ('8771c32f-c555-5c2d-8794-3b6cbc90d881', 'early', '/ˈɜːli/', 'adjective', 'happening before the usual or expected time', 'We had an early breakfast before the flight.', array[]::text[], array['late']::text[], 'A1', 'daily', null),
  ('360d69e6-90c1-587c-a540-3ed4e20709aa', 'quiet', '/ˈkwaɪət/', 'adjective', 'making very little noise', 'The library is a quiet place to study.', array['silent','calm']::text[], array['noisy','loud']::text[], 'A1', 'daily', null),
  ('687d6224-69be-5aec-a7a6-e9523a359399', 'holiday', '/ˈhɒlədeɪ/', 'noun', 'a period of time when you do not work or go to school, often spent travelling', 'We spent our summer holiday by the sea.', array['vacation','break']::text[], array[]::text[], 'A1', 'travel', null),
  ('30ada856-cf55-55de-abd8-374534ea158c', 'doctor', '/ˈdɒktə/', 'noun', 'a person whose job is to treat people who are ill or injured', 'You should see a doctor about that cough.', array['physician']::text[], array[]::text[], 'A1', 'health', null),
  ('a6a8f504-6a96-5036-b04e-8afad9a40bf6', 'healthy', '/ˈhelθi/', 'adjective', 'physically strong and not ill', 'Eating vegetables helps you stay healthy.', array['well','fit']::text[], array['ill','unhealthy']::text[], 'A1', 'health', null),
  ('fa2a60a7-3636-504e-b42a-f2b401363764', 'difficult', '/ˈdɪfɪkəlt/', 'adjective', 'not easy; needing a lot of effort or skill', 'The last question on the test was very difficult.', array['hard','tough']::text[], array['easy','simple']::text[], 'A1', 'education', null),
  ('030cfde6-34f2-5788-a3f3-7eac4bbb1d65', 'answer', '/ˈɑːnsə/', 'verb', 'to say or write something as a reply', 'Please answer all the questions on the page.', array['reply','respond']::text[], array['ask']::text[], 'A1', 'education', null),
  ('550a9868-73ac-5ae8-b869-3e18aa4953be', 'message', '/ˈmesɪdʒ/', 'noun', 'a short piece of written or spoken information that you send to someone', 'I sent my brother a message to say I was late.', array['note','text']::text[], array[]::text[], 'A1', 'technology', null),
  ('2e2de639-783f-5829-8bad-0023e6804660', 'city', '/ˈsɪti/', 'noun', 'a large and important town', 'Paris is a beautiful city to visit in spring.', array['metropolis']::text[], array['village']::text[], 'A1', 'travel', null),
  ('08747dcc-9256-5e08-ab2c-5e3fed1e2969', 'arrive', '/əˈraɪv/', 'verb', 'to reach a place at the end of a journey', 'Our train will arrive at nine o''clock.', array['reach','come']::text[], array['leave','depart']::text[], 'A1', 'travel', null),
  ('6f708465-a167-5745-974c-e5d956079115', 'friend', '/frend/', 'noun', 'a person you know well and like', 'My best friend lives next door.', array['companion','pal']::text[], array['enemy']::text[], 'A1', 'daily', null),
  ('2a549cf6-51bb-585d-a588-765db871e12a', 'help', '/help/', 'verb', 'to make it easier for someone to do something', 'Can you help me carry these bags?', array['assist','aid']::text[], array['hinder']::text[], 'A1', 'daily', null),
  ('3d3f0ed9-1c61-5b7d-aa79-a82c8e5c237e', 'busy', '/ˈbɪzi/', 'adjective', 'having a lot of things to do', 'I am busy this morning, but I can call you after lunch.', array['occupied']::text[], array['free','idle']::text[], 'A1', 'business', null),
  ('6070cc90-fe92-5325-aaf2-2d9198224d45', 'hot', '/hɒt/', 'adjective', 'having a high temperature', 'It is too hot to play football at midday.', array['boiling','warm']::text[], array['cold']::text[], 'A1', 'environment', null),
  ('4d568fea-f544-5836-b757-49aed85cf67e', 'learn', '/lɜːn/', 'verb', 'to get knowledge of something or a new skill', 'Children learn very quickly when they are curious.', array['study']::text[], array['forget']::text[], 'A1', 'education', null),
  ('a2a1f3d3-cad3-5bd3-8f67-61b7afe84162', 'big', '/bɪɡ/', 'adjective', 'large in size', 'They live in a big house with a garden.', array['large','huge']::text[], array['small','little']::text[], 'A1', 'daily', null),
  ('ff769c45-3f05-5f45-affe-be24d4ee4465', 'fast', '/fɑːst/', 'adjective', 'moving or able to move quickly', 'He has a fast car, but he always drives carefully.', array['quick','rapid']::text[], array['slow']::text[], 'A1', 'daily', null),
  ('65dbc8af-1918-56f4-99e1-11d4b934cce8', 'computer', '/kəmˈpjuːtə/', 'noun', 'an electronic machine that stores and processes information', 'She uses her computer to send emails and write reports.', array[]::text[], array[]::text[], 'A1', 'technology', null),
  ('9682731e-a3d9-538c-9671-f5c1e3443494', 'weather', '/ˈweðə/', 'noun', 'the conditions in the air at a particular time, such as rain, sun or wind', 'The weather was sunny and warm all weekend.', array[]::text[], array[]::text[], 'A1', 'environment', null),
  ('edc57d65-7eb2-5568-a0fd-e8d85683cf53', 'borrow', '/ˈbɒrəʊ/', 'verb', 'to take and use something that belongs to someone else and give it back later', 'Can I borrow your pen for a minute?', array[]::text[], array['lend']::text[], 'A2', 'daily', null),
  ('d363c153-fe31-5af9-b38f-97b7e833a5ee', 'journey', '/ˈdʒɜːni/', 'noun', 'an act of travelling from one place to another', 'The journey from London to Edinburgh takes about four hours.', array['trip','voyage']::text[], array[]::text[], 'A2', 'travel', null),
  ('30547a9d-9fc3-5333-b67d-bdb2bddda393', 'luggage', '/ˈlʌɡɪdʒ/', 'noun', 'the bags and cases you take with you when you travel', 'Please do not leave your luggage unattended.', array['baggage']::text[], array[]::text[], 'A2', 'travel', null),
  ('a010b364-afcc-5787-a6bd-39a2704dbf79', 'advice', '/ədˈvaɪs/', 'noun', 'an opinion someone gives you about what you should do', 'My teacher gave me some useful advice about the exam.', array['guidance','recommendation']::text[], array[]::text[], 'A2', 'education', null),
  ('43e63a42-9490-5c9f-aec1-420757b156f0', 'improve', '/ɪmˈpruːv/', 'verb', 'to become better or to make something better', 'Reading every day will improve your vocabulary.', array['enhance','develop']::text[], array['worsen']::text[], 'A2', 'education', null),
  ('960d7993-7735-5b80-8020-be3691a97411', 'polite', '/pəˈlaɪt/', 'adjective', 'behaving in a way that shows respect for other people', 'It is polite to say thank you when someone helps you.', array['courteous','respectful']::text[], array['rude','impolite']::text[], 'A2', 'daily', null),
  ('cca9f584-965e-564a-8e91-6acfc18c95e4', 'delicious', '/dɪˈlɪʃəs/', 'adjective', 'having a very pleasant taste or smell', 'My grandmother makes delicious soup.', array['tasty']::text[], array['tasteless']::text[], 'A2', 'daily', null),
  ('0833ea65-8464-569e-adc4-1c1a2816c8a8', 'dangerous', '/ˈdeɪndʒərəs/', 'adjective', 'likely to cause harm or injury', 'It is dangerous to swim in the river after heavy rain.', array['risky','unsafe']::text[], array['safe']::text[], 'A2', 'daily', null),
  ('318c11ca-7451-5d2d-8f1d-c42a5b6fc1ce', 'pollution', '/pəˈluːʃn/', 'noun', 'damage to air, water or land caused by harmful substances', 'Traffic is a major cause of air pollution in big cities.', array['contamination']::text[], array[]::text[], 'A2', 'environment', null),
  ('b83bd4f8-48e7-57a6-a688-f2966f45b9fc', 'recycle', '/ˌriːˈsaɪkl/', 'verb', 'to treat used materials so that they can be used again', 'We recycle all our glass bottles and newspapers.', array['reuse','reprocess']::text[], array['discard']::text[], 'A2', 'environment', null),
  ('f662b147-4ae6-5258-9b44-bc0aa7775d63', 'salary', '/ˈsæləri/', 'noun', 'a fixed amount of money paid to an employee, usually every month', 'She received a higher salary when she was promoted.', array['wage','pay','income']::text[], array[]::text[], 'A2', 'business', null),
  ('67660f06-9639-5fb0-902f-c1f7e556a9b4', 'interview', '/ˈɪntəvjuː/', 'noun', 'a formal meeting in which someone is asked questions, for example to decide whether to give them a job', 'He wore a suit to his job interview.', array[]::text[], array[]::text[], 'A2', 'business', null),
  ('ce13b132-cdc3-5b70-9492-8eaaf4939eee', 'medicine', '/ˈmedsn/', 'noun', 'a substance that you take to treat an illness', 'Take this medicine twice a day after meals.', array['medication','drug']::text[], array[]::text[], 'A2', 'health', null),
  ('88d0e097-2ea6-5b1f-9071-5a9fe1077c25', 'download', '/ˌdaʊnˈləʊd/', 'verb', 'to copy data from the internet onto a computer or phone', 'You can download the app for free.', array[]::text[], array['upload']::text[], 'A2', 'technology', null),
  ('f510f61b-fccc-526a-b5d5-0457e5b3639b', 'careful', '/ˈkeəfl/', 'adjective', 'giving attention to what you are doing to avoid mistakes or danger', 'Be careful when you cross the road.', array['cautious','attentive']::text[], array['careless']::text[], 'A2', 'daily', null),
  ('66279405-945d-5491-a43f-8a1af8904598', 'noisy', '/ˈnɔɪzi/', 'adjective', 'making a lot of loud or unpleasant noise', 'The street outside my window is very noisy at night.', array['loud']::text[], array['quiet','silent']::text[], 'A2', 'daily', null),
  ('bd1b1891-b241-5d52-b32c-d06fefb01910', 'explain', '/ɪkˈspleɪn/', 'verb', 'to make something clear or easy to understand', 'Could you explain this word to me?', array['clarify','describe']::text[], array[]::text[], 'A2', 'education', null),
  ('424b8fc9-90fd-594c-a497-86226bc1d8ab', 'experiment', '/ɪkˈsperɪmənt/', 'noun', 'a scientific test done to learn something or to prove an idea', 'The students did an experiment to see how plants grow in the dark.', array['test','trial']::text[], array[]::text[], 'A2', 'science', null),
  ('4c145145-a370-5616-b5c8-b32ebd65f3de', 'customer', '/ˈkʌstəmə/', 'noun', 'a person who buys goods or services from a shop or business', 'The shop gives every customer a free bag.', array['client','buyer']::text[], array['seller']::text[], 'A2', 'business', null),
  ('cee35464-3365-550e-a280-ed6b2cbe2a34', 'exercise', '/ˈeksəsaɪz/', 'noun', 'physical activity that you do to stay healthy', 'Regular exercise can improve your mood.', array['workout','training']::text[], array[]::text[], 'A2', 'health', null),
  ('67af748f-3968-5314-b911-e88f12d62058', 'similar', '/ˈsɪmələ/', 'adjective', 'almost the same but not exactly', 'My sister and I have similar tastes in music.', array['alike','comparable']::text[], array['different']::text[], 'A2', 'education', null),
  ('17a21175-c3f0-5d6d-955f-3a00f01664d8', 'cancel', '/ˈkænsl/', 'verb', 'to decide that a planned event will not happen', 'The airline had to cancel our flight because of the storm.', array['call off','scrap']::text[], array['confirm']::text[], 'A2', 'travel', null),
  ('00a256b2-411e-5823-a7b0-a4c0e0d1811a', 'invite', '/ɪnˈvaɪt/', 'verb', 'to ask someone to come to an event', 'We want to invite all our neighbours to the party.', array['ask']::text[], array[]::text[], 'A2', 'daily', null),
  ('0f38a419-7172-52a3-9543-e306c01c458a', 'brave', '/breɪv/', 'adjective', 'willing to do dangerous or difficult things without showing fear', 'The brave firefighter ran into the burning house.', array['courageous','fearless']::text[], array['cowardly','afraid']::text[], 'A2', 'daily', null),
  ('344579dd-72f4-5e87-b9a2-ea69066c90c7', 'lonely', '/ˈləʊnli/', 'adjective', 'unhappy because you are alone or have no friends', 'He felt lonely when he first moved to the new city.', array['isolated']::text[], array[]::text[], 'A2', 'health', null),
  ('b3867c9e-44f6-59f2-863a-c34bc2c88802', 'look after', '/lʊk ˈɑːftə/', 'phrasal verb', 'to take care of someone or something', 'Can you look after my cat while I am away?', array['take care of','care for']::text[], array['neglect']::text[], 'A2', 'phrasal_verbs', null),
  ('288fd1b9-1cf5-587e-a7de-bbe34eb363c0', 'find out', '/faɪnd ˈaʊt/', 'phrasal verb', 'to discover a fact or piece of information', 'I need to find out what time the museum opens.', array['discover']::text[], array[]::text[], 'A2', 'phrasal_verbs', null),
  ('608db264-0182-597c-a8cc-326f03852119', 'usually', '/ˈjuːʒuəli/', 'adverb', 'in most cases; normally', 'I usually walk to work, but today I took the bus.', array['normally','generally']::text[], array['rarely','seldom']::text[], 'A2', 'daily', null),
  ('1e9632f0-6304-5567-929c-78d68ffdeb4b', 'postpone', '/pəˈspəʊn/', 'verb', 'to arrange for an event to happen at a later time than planned', 'They decided to postpone the meeting until next week.', array['delay','defer']::text[], array['bring forward']::text[], 'B1', 'business', null),
  ('d718fd04-b785-56a1-a53b-aecb9993de7c', 'reliable', '/rɪˈlaɪəbl/', 'adjective', 'able to be trusted or depended on', 'We need a reliable supplier who always delivers on time.', array['dependable','trustworthy']::text[], array['unreliable']::text[], 'B1', 'business', null),
  ('d286a53c-c32e-5407-8624-c1056ef278ff', 'exhausted', '/ɪɡˈzɔːstɪd/', 'adjective', 'extremely tired', 'After the marathon, the runners were exhausted.', array['worn out','drained']::text[], array['energetic','refreshed']::text[], 'B1', 'health', null),
  ('79a185ea-2cfc-57cf-993e-e10414eb743c', 'environment', '/ɪnˈvaɪrənmənt/', 'noun', 'the natural world, including the land, air, water, plants and animals', 'Plastic waste is harming the environment.', array['nature','surroundings']::text[], array[]::text[], 'B1', 'environment', null),
  ('75083e86-cf7c-5b25-b0a5-e6e4a0501dca', 'opportunity', '/ˌɒpəˈtjuːnəti/', 'noun', 'a situation that makes it possible to do something you want to do', 'Studying abroad gave her the opportunity to learn a new language.', array['chance','opening']::text[], array[]::text[], 'B1', 'business', null),
  ('26b31296-b246-5238-bdac-17dde35e0bec', 'efficient', '/ɪˈfɪʃnt/', 'adjective', 'working well without wasting time, energy or money', 'LED bulbs are more efficient than old light bulbs.', array['effective','productive']::text[], array['inefficient','wasteful']::text[], 'B1', 'technology', null),
  ('f33a98de-60af-505d-9d2e-2e7a2e881296', 'curious', '/ˈkjʊəriəs/', 'adjective', 'wanting to know or learn about something', 'Young children are naturally curious about the world.', array['inquisitive','interested']::text[], array['indifferent','uninterested']::text[], 'B1', 'education', null),
  ('14d69394-7da4-5c7d-a5ca-1759a594fcda', 'purchase', '/ˈpɜːtʃəs/', 'verb', 'to buy something, especially something expensive or important', 'The company plans to purchase new equipment this year.', array['buy','acquire']::text[], array['sell']::text[], 'B1', 'business', null),
  ('8e0a208b-a4fb-57ec-a27b-bbb7a8c4671c', 'symptom', '/ˈsɪmptəm/', 'noun', 'a sign that someone has an illness', 'A high temperature is a common symptom of flu.', array['sign','indication']::text[], array[]::text[], 'B1', 'health', null),
  ('620a2fd9-46bf-590e-8bf8-e43c498fc487', 'accommodation', '/əˌkɒməˈdeɪʃn/', 'noun', 'a place to live or stay, such as a hotel room or a flat', 'The university helps new students find accommodation.', array['lodging','housing']::text[], array[]::text[], 'B1', 'travel', null),
  ('71d6433f-a991-559c-8a4b-d75f4edad93f', 'destination', '/ˌdestɪˈneɪʃn/', 'noun', 'the place that someone is travelling to', 'Bali is a popular holiday destination.', array[]::text[], array[]::text[], 'B1', 'travel', null),
  ('877aaa22-d118-5fb5-92f3-8344c2917945', 'evidence', '/ˈevɪdəns/', 'noun', 'facts or signs that show that something is true', 'There is strong evidence that smoking causes cancer.', array['proof','data']::text[], array[]::text[], 'B1', 'science', null),
  ('dd3068f3-0075-5d35-8680-69a883a0df2a', 'affect', '/əˈfekt/', 'verb', 'to have an influence on someone or something', 'Lack of sleep can affect your concentration.', array['influence','impact']::text[], array[]::text[], 'B1', 'science', null),
  ('5cf73469-a907-513e-9fd5-a308ddd5607f', 'global', '/ˈɡləʊbl/', 'adjective', 'relating to the whole world', 'Climate change is a global problem.', array['worldwide','international']::text[], array['local']::text[], 'B1', 'environment', null),
  ('83133917-add3-557d-aee2-8e49211edb28', 'device', '/dɪˈvaɪs/', 'noun', 'a machine or tool made for a particular purpose', 'This small device measures your heart rate.', array['gadget','instrument']::text[], array[]::text[], 'B1', 'technology', null),
  ('efd7053d-a538-5e68-8576-2373f56ecdf1', 'confident', '/ˈkɒnfɪdənt/', 'adjective', 'feeling sure about your own abilities', 'After weeks of practice, she felt confident about the exam.', array['self-assured','sure']::text[], array['insecure','nervous']::text[], 'B1', 'education', null),
  ('87b4f5d1-19e9-5997-ae12-287f3f40a987', 'deadline', '/ˈdedlaɪn/', 'noun', 'a time or date by which something must be done', 'The deadline for the application is Friday at noon.', array['time limit','due date']::text[], array[]::text[], 'B1', 'business', null),
  ('381ae099-49aa-5934-ab14-4d9b6b007295', 'generous', '/ˈdʒenərəs/', 'adjective', 'willing to give money, help or time freely', 'It was generous of you to pay for everyone''s dinner.', array['kind','charitable']::text[], array['mean','selfish']::text[], 'B1', 'daily', null),
  ('c88e8ac6-8135-59fa-a4c7-d0536d5a20c7', 'ancient', '/ˈeɪnʃənt/', 'adjective', 'very old; from a long time ago', 'We visited the ruins of an ancient temple.', array['historic','old']::text[], array['modern','new']::text[], 'B1', 'academic', null),
  ('7bc7d335-3deb-58fb-8135-0d6d22770737', 'compare', '/kəmˈpeə/', 'verb', 'to examine how two or more things are similar or different', 'It is useful to compare prices before you buy a phone.', array['contrast','weigh up']::text[], array[]::text[], 'B1', 'academic', null),
  ('f7865268-587c-554f-a470-e5759cc2149a', 'give up', '/ɡɪv ˈʌp/', 'phrasal verb', 'to stop doing or trying to do something', 'Do not give up now — you are nearly at the finish line!', array['quit','abandon']::text[], array['persevere','continue']::text[], 'B1', 'phrasal_verbs', null),
  ('cddbfd58-4646-52eb-93de-cd72feffbefa', 'put off', '/pʊt ˈɒf/', 'phrasal verb', 'to delay doing something until a later time', 'Stop trying to put off your homework until tomorrow.', array['postpone','delay']::text[], array['bring forward']::text[], 'B1', 'phrasal_verbs', null),
  ('349130d1-40c8-5c1d-aecc-adfdde3293e2', 'break the ice', '/breɪk ði aɪs/', 'idiom', 'to say or do something that makes people feel relaxed when they first meet', 'The teacher played a game to break the ice on the first day.', array[]::text[], array[]::text[], 'B1', 'idioms', null),
  ('337e656b-99ee-585b-9a1a-c6a1a44164b2', 'a piece of cake', '/ə piːs əv keɪk/', 'idiom', 'something that is very easy to do', 'For her, the maths test was a piece of cake.', array['a breeze','child''s play']::text[], array['an uphill battle']::text[], 'B1', 'idioms', null),
  ('65886035-57fe-510e-93d3-264d2bb7511f', 'habit', '/ˈhæbɪt/', 'noun', 'something that you do regularly, often without thinking about it', 'Brushing your teeth twice a day is a good habit.', array['routine','custom']::text[], array[]::text[], 'B1', 'health', null),
  ('46e4682c-4d18-53a8-9544-34fe1b64cd93', 'predict', '/prɪˈdɪkt/', 'verb', 'to say that something will happen in the future', 'Scientists predict that sea levels will continue to rise.', array['forecast','foresee']::text[], array[]::text[], 'B1', 'science', null),
  ('5510c507-d131-5ab7-a2ef-9a0bfb6db589', 'gradually', '/ˈɡrædʒuəli/', 'adverb', 'slowly, over a period of time', 'The number of visitors gradually increased over the decade.', array['steadily','progressively']::text[], array['suddenly','abruptly']::text[], 'B1', 'ielts_academic', 'Common in IELTS Writing Task 1 descriptions of trends.'),
  ('b317d572-220c-595c-8d27-7b7543e1397b', 'meticulous', '/məˈtɪkjələs/', 'adjective', 'very careful and precise, paying attention to every detail', 'She kept meticulous records of every experiment.', array['thorough','precise','painstaking']::text[], array['careless','sloppy']::text[], 'B2', 'academic', null),
  ('91e67c5c-3756-5e3a-9df0-cf37c877def8', 'abundant', '/əˈbʌndənt/', 'adjective', 'existing in large quantities; more than enough', 'The region has abundant supplies of fresh water.', array['plentiful','ample','copious']::text[], array['scarce','sparse']::text[], 'B2', 'environment', null),
  ('619dc139-33ef-5d1c-8454-e8822cc7af9c', 'reluctant', '/rɪˈlʌktənt/', 'adjective', 'not willing to do something and therefore slow to do it', 'He was reluctant to admit that he had made a mistake.', array['unwilling','hesitant']::text[], array['willing','eager']::text[], 'B2', 'daily', null),
  ('cb4690fc-ac23-55d6-a261-95781db5a601', 'interruption', '/ˌɪntəˈrʌpʃn/', 'noun', 'something that stops an activity or a process for a short time', 'Despite the heavy rain, the match continued without any interruption.', array['disruption','pause']::text[], array['continuation']::text[], 'B2', 'daily', null),
  ('f62a5b1d-78b4-52ce-9823-e605447f4a74', 'sustainable', '/səˈsteɪnəbl/', 'adjective', 'able to continue for a long time without damaging the environment', 'The city is investing in sustainable public transport.', array['renewable','eco-friendly']::text[], array['unsustainable']::text[], 'B2', 'environment', 'Very common in IELTS Writing Task 2 essays about the environment.'),
  ('fe06b3c0-7ce0-5607-944d-54a828e52b92', 'inevitable', '/ɪnˈevɪtəbl/', 'adjective', 'certain to happen and impossible to avoid', 'With so little preparation, failure seemed inevitable.', array['unavoidable','certain']::text[], array['avoidable','uncertain']::text[], 'B2', 'academic', null),
  ('15430f6a-7c52-51bf-9f66-7a3511753240', 'significant', '/sɪɡˈnɪfɪkənt/', 'adjective', 'large or important enough to have an effect or to be noticed', 'There has been a significant increase in online shopping.', array['considerable','substantial','notable']::text[], array['insignificant','minor','negligible']::text[], 'B2', 'ielts_academic', 'Useful for describing trends in IELTS Writing Task 1.'),
  ('3076f5db-70c2-56f7-9bbf-4829491b834e', 'consequence', '/ˈkɒnsɪkwəns/', 'noun', 'a result of an action or situation, often a bad one', 'Rising sea levels are a direct consequence of global warming.', array['result','outcome','effect']::text[], array['cause']::text[], 'B2', 'ielts_academic', 'Use it to explain cause-and-effect relationships in Task 2 essays.'),
  ('be0d7c21-3d2d-5d06-9a63-49a57c05a63d', 'negotiate', '/nɪˈɡəʊʃieɪt/', 'verb', 'to discuss something formally in order to reach an agreement', 'The union will negotiate with management over pay.', array['bargain','discuss']::text[], array[]::text[], 'B2', 'business', null),
  ('4c0edeb4-9ddf-5cbf-862d-99779d576422', 'revenue', '/ˈrevənjuː/', 'noun', 'the income that a business or government receives', 'The company''s revenue grew by 20 percent last year.', array['income','earnings','turnover']::text[], array['expenditure','costs']::text[], 'B2', 'business', null),
  ('1bd2ac97-76b3-56c2-bf51-25ff520a19ad', 'innovation', '/ˌɪnəˈveɪʃn/', 'noun', 'a new idea, method or product', 'Smartphones were a major innovation in communication.', array['invention','breakthrough']::text[], array[]::text[], 'B2', 'technology', null),
  ('559745df-dbe0-5dc6-8d14-201b303e2d54', 'obsolete', '/ˈɒbsəliːt/', 'adjective', 'no longer used because something newer exists', 'Fax machines have become almost obsolete.', array['outdated','antiquated']::text[], array['modern','current']::text[], 'B2', 'technology', null),
  ('aeeb25f9-3ebe-5da1-88cd-f5a8c439a38c', 'diagnose', '/ˈdaɪəɡnəʊz/', 'verb', 'to identify an illness by examining someone', 'Doctors can now diagnose the disease with a simple blood test.', array['identify','detect']::text[], array[]::text[], 'B2', 'health', null),
  ('ed74341e-6491-55a7-a8c4-01596e639e15', 'hypothesis', '/haɪˈpɒθəsɪs/', 'noun', 'an idea suggested as a possible explanation that can then be tested', 'The experiment was designed to test the hypothesis.', array['theory','proposition']::text[], array[]::text[], 'B2', 'science', null),
  ('7dac0c74-8adf-5538-9d2b-4e12100edf3f', 'ambiguous', '/æmˈbɪɡjuəs/', 'adjective', 'having more than one possible meaning', 'The instructions were ambiguous, so nobody knew what to do.', array['unclear','vague']::text[], array['clear','explicit']::text[], 'B2', 'academic', null),
  ('0d8f8277-8278-5152-97d7-45b06197906e', 'deteriorate', '/dɪˈtɪəriəreɪt/', 'verb', 'to become worse', 'His health began to deteriorate after the accident.', array['worsen','decline']::text[], array['improve']::text[], 'B2', 'ielts_academic', 'Useful in Task 1 and Task 2 to describe negative change.'),
  ('a1ef190e-5f0e-572f-87fe-9c174018cd7d', 'compulsory', '/kəmˈpʌlsəri/', 'adjective', 'required by a law or a rule', 'Education is compulsory for children between the ages of five and sixteen.', array['mandatory','obligatory']::text[], array['optional','voluntary']::text[], 'B2', 'education', null),
  ('57616ff2-e978-5840-92de-27903856d120', 'curriculum', '/kəˈrɪkjələm/', 'noun', 'the subjects and content taught in a school, college or course', 'Coding is now part of the national curriculum.', array['syllabus','programme']::text[], array[]::text[], 'B2', 'education', null),
  ('0866cad6-3641-5e59-996e-4138d27ee707', 'bring about', '/brɪŋ əˈbaʊt/', 'phrasal verb', 'to cause something to happen', 'The internet has helped to bring about huge changes in how we work.', array['cause','produce']::text[], array['prevent']::text[], 'B2', 'phrasal_verbs', null),
  ('3369f3e5-09f3-5785-b99f-0cffbf39cd59', 'carry out', '/ˈkæri aʊt/', 'phrasal verb', 'to do or complete a task, especially an official one', 'Researchers will carry out a survey of 2,000 households.', array['conduct','perform']::text[], array[]::text[], 'B2', 'phrasal_verbs', null),
  ('8ebd58b0-56e6-5031-ba90-2183ca525b42', 'hit the nail on the head', '/hɪt ðə neɪl ɒn ðə hed/', 'idiom', 'to describe exactly what is causing a situation or problem', 'You hit the nail on the head when you said the real issue is cost.', array['be spot on']::text[], array[]::text[], 'B2', 'idioms', null),
  ('5b2f7f14-8bca-5b52-b276-fc97f874d3f4', 'cost an arm and a leg', '/kɒst ən ɑːm ənd ə leɡ/', 'idiom', 'to be extremely expensive', 'That designer jacket must cost an arm and a leg.', array[]::text[], array['cost next to nothing']::text[], 'B2', 'idioms', null),
  ('15086fb5-d8ed-5275-b8ea-12aab2280628', 'versatile', '/ˈvɜːsətaɪl/', 'adjective', 'able to be used for many different purposes or to do many different things', 'A smartphone is a remarkably versatile device.', array['adaptable','multipurpose']::text[], array['limited','inflexible']::text[], 'B2', 'technology', null),
  ('4b9ecd7f-cb98-565a-9ea3-b92bc749f66c', 'emission', '/iˈmɪʃn/', 'noun', 'gas or another substance that is sent out into the air', 'Each car''s emission levels are tested every year.', array['discharge','release']::text[], array[]::text[], 'B2', 'environment', null),
  ('79002494-e178-5741-bfb7-b10213c5d03e', 'thrive', '/θraɪv/', 'verb', 'to grow, develop or be successful', 'These plants thrive in hot, dry conditions.', array['flourish','prosper']::text[], array['decline','wither']::text[], 'B2', 'environment', null),
  ('95854c52-4403-541e-8138-575631434aed', 'a blessing in disguise', '/ə ˈblesɪŋ ɪn dɪsˈɡaɪz/', 'idiom', 'something that seems bad at first but turns out to be good', 'Losing that job was a blessing in disguise because I found a better one.', array[]::text[], array[]::text[], 'B2', 'idioms', null),
  ('be069d18-347b-5a43-aa4e-ecb29f15dd61', 'approximately', '/əˈprɒksɪmətli/', 'adverb', 'close to but not exactly a particular number or amount', 'The survey included approximately 2,000 people.', array['roughly','about']::text[], array['exactly','precisely']::text[], 'B2', 'ielts_academic', 'Use it to report figures in IELTS Writing Task 1.'),
  ('a0660363-cf78-5c07-a693-cf6d3fa96503', 'ubiquitous', '/juːˈbɪkwɪtəs/', 'adjective', 'seeming to be everywhere at the same time', 'Smartphones have become ubiquitous in modern life.', array['omnipresent','pervasive','widespread']::text[], array['rare','scarce']::text[], 'C1', 'technology', null),
  ('77fb76c2-f1e9-5fd2-89a7-aaf031c6dc27', 'scrutinise', '/ˈskruːtənaɪz/', 'verb', 'to examine something very carefully', 'Investors will scrutinise the company''s accounts.', array['examine','inspect']::text[], array['overlook','ignore']::text[], 'C1', 'academic', null),
  ('6b285742-b117-58e8-93ed-fb5e374ddca3', 'mitigate', '/ˈmɪtɪɡeɪt/', 'verb', 'to make something bad less severe or harmful', 'Planting trees can help mitigate the effects of flooding.', array['alleviate','lessen']::text[], array['aggravate','intensify']::text[], 'C1', 'ielts_academic', 'A strong academic verb for proposing solutions in Task 2.'),
  ('89b54198-de37-5354-a7fd-42a57aece36e', 'pragmatic', '/præɡˈmætɪk/', 'adjective', 'dealing with problems in a practical way rather than following theories or ideals', 'We need a pragmatic solution that can be put in place quickly.', array['practical','realistic']::text[], array['idealistic','impractical']::text[], 'C1', 'business', null),
  ('c765096d-36e3-5fbe-ae5e-197511ee82f1', 'eloquent', '/ˈeləkwənt/', 'adjective', 'able to express ideas clearly and persuasively', 'She gave an eloquent speech about education reform.', array['articulate','persuasive']::text[], array['inarticulate']::text[], 'C1', 'education', null),
  ('03ff5f3d-c500-5e47-b9c8-37b9acc9f664', 'resilient', '/rɪˈzɪliənt/', 'adjective', 'able to recover quickly from difficulties', 'Children are often more resilient than adults expect.', array['tough','hardy']::text[], array['fragile','vulnerable']::text[], 'C1', 'health', null),
  ('db640383-a256-5306-aaa3-5160c4af4765', 'comprehensive', '/ˌkɒmprɪˈhensɪv/', 'adjective', 'including everything or nearly everything', 'The guide gives a comprehensive overview of the topic.', array['thorough','extensive']::text[], array['partial','incomplete']::text[], 'C1', 'ielts_academic', null),
  ('c41f5a33-1225-52be-abb1-7872f6cd5881', 'detrimental', '/ˌdetrɪˈmentl/', 'adjective', 'causing harm or damage', 'Too much screen time can be detrimental to sleep.', array['harmful','damaging']::text[], array['beneficial','advantageous']::text[], 'C1', 'health', null),
  ('dd4d32fd-a9eb-5799-9818-a69d9e556dfc', 'unprecedented', '/ʌnˈpresɪdentɪd/', 'adjective', 'never having happened or existed before', 'The pandemic caused unprecedented disruption to schools.', array['unparalleled','unheard of']::text[], array['common','familiar']::text[], 'C1', 'ielts_academic', 'Effective for emphasising the scale of a change in Task 1 and Task 2.'),
  ('25301e40-8a54-550a-8086-d1b8cb612869', 'alleviate', '/əˈliːvieɪt/', 'verb', 'to make pain or a problem less severe', 'The medicine helped to alleviate her pain.', array['ease','relieve']::text[], array['aggravate','worsen']::text[], 'C1', 'health', null),
  ('0865003b-36db-57f3-9b73-4ed3a5a93675', 'feasible', '/ˈfiːzəbl/', 'adjective', 'possible and practical to do', 'Building the bridge in six months is not feasible.', array['viable','achievable']::text[], array['impossible','impractical']::text[], 'C1', 'business', null),
  ('6e93632c-2acf-583d-81f8-5466ab5cbc40', 'advocate', '/ˈædvəkeɪt/', 'verb', 'to publicly support or recommend a policy or idea', 'Many experts advocate a shorter working week.', array['champion','promote']::text[], array['oppose','criticise']::text[], 'C1', 'academic', null),
  ('91191644-3059-5815-b3a6-7cd5ef187951', 'discrepancy', '/dɪˈskrepənsi/', 'noun', 'a difference between things that should be the same', 'Auditors found a discrepancy between the two sets of figures.', array['inconsistency','disparity','mismatch']::text[], array['consistency','agreement']::text[], 'C1', 'business', null),
  ('d2deb9f7-b62a-5eab-8d4f-a5a3f8598488', 'empirical', '/ɪmˈpɪrɪkl/', 'adjective', 'based on observation or experiment rather than theory', 'There is little empirical evidence to support the claim.', array['observed','experimental']::text[], array['theoretical','hypothetical']::text[], 'C1', 'science', null),
  ('a45c9094-d96d-5c44-8294-6eb9846b06cd', 'proliferation', '/prəˌlɪfəˈreɪʃn/', 'noun', 'a rapid increase in the number or amount of something', 'The proliferation of social media has changed how news spreads.', array['spread','expansion']::text[], array['decline','reduction']::text[], 'C1', 'technology', null),
  ('34286cbd-e1a8-5a34-93ab-238a512da15a', 'biodiversity', '/ˌbaɪəʊdaɪˈvɜːsəti/', 'noun', 'the variety of plant and animal life in a particular habitat', 'Rainforests have extremely high levels of biodiversity.', array[]::text[], array[]::text[], 'C1', 'environment', null),
  ('dba811d5-5a74-5e91-9902-3bf2df055411', 'phase out', '/feɪz ˈaʊt/', 'phrasal verb', 'to gradually stop using or providing something', 'The government plans to phase out petrol cars by 2035.', array['discontinue','withdraw']::text[], array['introduce','phase in']::text[], 'C1', 'phrasal_verbs', null),
  ('d3d90607-12e3-5fd4-a50f-20446966c2a0', 'come up with', '/kʌm ˈʌp wɪð/', 'phrasal verb', 'to think of an idea, plan or solution', 'We need to come up with a better marketing strategy.', array['devise','think up']::text[], array[]::text[], 'C1', 'phrasal_verbs', null),
  ('9c7be3f8-7d3b-53d5-98a4-e1e6dd7b5d80', 'the tip of the iceberg', '/ðə tɪp əv ði ˈaɪsbɜːɡ/', 'idiom', 'a small, visible part of a much larger problem', 'The reported cases are just the tip of the iceberg.', array[]::text[], array[]::text[], 'C1', 'idioms', null),
  ('733b8539-c5c3-5cc0-aead-bdf0057b6f80', 'cut corners', '/kʌt ˈkɔːnəz/', 'idiom', 'to do something cheaply or quickly by ignoring rules or lowering quality', 'The builders cut corners, and the roof started leaking within a year.', array['skimp']::text[], array[]::text[], 'C1', 'idioms', null),
  ('719a19d3-3145-5c13-8c4c-06d0688f9a19', 'conscientious', '/ˌkɒnʃiˈenʃəs/', 'adjective', 'careful to do your work well and thoroughly', 'She is a conscientious student who never misses a deadline.', array['diligent','dutiful']::text[], array['negligent','careless']::text[], 'C1', 'education', null),
  ('cf22a0ce-c4df-5177-bcd9-254fa006c299', 'ambivalent', '/æmˈbɪvələnt/', 'adjective', 'having mixed feelings about something', 'Many residents are ambivalent about the new shopping centre.', array['conflicted','undecided']::text[], array['certain','decided']::text[], 'C1', 'daily', null),
  ('5e2261f3-1199-5348-91b9-fa8ba8673aec', 'lucrative', '/ˈluːkrətɪv/', 'adjective', 'producing a lot of profit', 'He left teaching for a more lucrative career in finance.', array['profitable','well-paid']::text[], array['unprofitable','loss-making']::text[], 'C1', 'business', null),
  ('fd5f62b5-f240-5877-ae06-9bb387b56d5d', 'infrastructure', '/ˈɪnfrəstrʌktʃə/', 'noun', 'the basic systems and services that a country or organisation needs, such as roads, power and communications', 'The government is investing heavily in rural infrastructure.', array['facilities','framework']::text[], array[]::text[], 'C1', 'technology', null),
  ('f23fc6c4-35e3-5364-9ccf-edae26bd4e15', 'sedentary', '/ˈsedntri/', 'adjective', 'involving a lot of sitting and little physical activity', 'A sedentary lifestyle increases the risk of heart disease.', array['inactive','desk-bound']::text[], array['active']::text[], 'C1', 'health', null),
  ('94c470db-836e-50bb-8157-3c66b18509bb', 'undermine', '/ˌʌndəˈmaɪn/', 'verb', 'to gradually make something weaker or less effective', 'Constant criticism can undermine a person''s confidence.', array['weaken','erode']::text[], array['strengthen','reinforce']::text[], 'C1', 'academic', null),
  ('730cc527-2d22-5e1d-9a7f-f0bc089c4df4', 'simultaneously', '/ˌsɪmlˈteɪniəsli/', 'adverb', 'at exactly the same time', 'The film was released simultaneously in forty countries.', array['concurrently','at once']::text[], array['separately','consecutively']::text[], 'C1', 'academic', null),
  ('c98db150-7bb8-5cdd-88e6-fa5b37b83c3e', 'ephemeral', '/ɪˈfemərəl/', 'adjective', 'lasting for a very short time', 'Fame on social media is often ephemeral.', array['fleeting','transient','short-lived']::text[], array['permanent','enduring']::text[], 'C2', 'academic', null),
  ('357116aa-c099-5ab3-b306-fed0ddbd0abc', 'obfuscate', '/ˈɒbfʌskeɪt/', 'verb', 'to make something deliberately unclear or difficult to understand', 'The report seemed designed to obfuscate the real costs.', array['obscure','muddle']::text[], array['clarify','elucidate']::text[], 'C2', 'academic', null),
  ('24bc2aaf-3057-5f95-afdf-d5e50386a104', 'perfunctory', '/pəˈfʌŋktəri/', 'adjective', 'done quickly and without real care or interest, only because it is expected', 'He gave the document a perfunctory glance before signing it.', array['cursory','superficial']::text[], array['thorough','careful']::text[], 'C2', 'business', null),
  ('258456c0-3b3e-5e51-ae50-d340f33a91bb', 'quintessential', '/ˌkwɪntɪˈsenʃl/', 'adjective', 'representing the most perfect or typical example of something', 'Afternoon tea is a quintessential English tradition.', array['archetypal','classic']::text[], array['atypical','unrepresentative']::text[], 'C2', 'daily', null),
  ('f32676e2-ffd9-5f1c-8996-c7c9b38c75ad', 'ameliorate', '/əˈmiːliəreɪt/', 'verb', 'to make a bad or unsatisfactory situation better', 'New policies were introduced to ameliorate living conditions in the area.', array['improve','better']::text[], array['worsen','exacerbate']::text[], 'C2', 'health', null),
  ('23bad80e-9ad8-500e-a29d-b2421a2f02ac', 'exacerbate', '/ɪɡˈzæsəbeɪt/', 'verb', 'to make a problem, situation or illness worse', 'Stress can exacerbate skin conditions.', array['aggravate','intensify']::text[], array['alleviate','relieve']::text[], 'C2', 'health', null),
  ('3546e3cd-ee16-5baf-8a67-e2531b733850', 'idiosyncratic', '/ˌɪdiəsɪŋˈkrætɪk/', 'adjective', 'peculiar to an individual; unusual and distinctive', 'The author''s idiosyncratic style is instantly recognisable.', array['distinctive','eccentric']::text[], array['conventional','ordinary']::text[], 'C2', 'daily', null),
  ('3cab9f80-f185-5cef-af8b-446421c4c391', 'juxtapose', '/ˌdʒʌkstəˈpəʊz/', 'verb', 'to place things side by side in order to compare or contrast them', 'The film-maker likes to juxtapose scenes of wealth and poverty.', array['contrast','set side by side']::text[], array['separate']::text[], 'C2', 'academic', null),
  ('54320ac2-51bf-51d4-92e0-002415dbada9', 'pernicious', '/pəˈnɪʃəs/', 'adjective', 'having a harmful effect, especially gradually or in a way that is not easily noticed', 'Misinformation can have a pernicious influence on public health.', array['insidious','damaging']::text[], array['benign','harmless']::text[], 'C2', 'health', null),
  ('2da6cc2d-eeb2-54c9-bb69-8db4b57125a2', 'recalcitrant', '/rɪˈkælsɪtrənt/', 'adjective', 'unwilling to obey or cooperate', 'The teacher struggled to manage a few recalcitrant pupils.', array['uncooperative','defiant','unruly']::text[], array['obedient','compliant']::text[], 'C2', 'education', null),
  ('355c5103-e57b-591e-84d2-39a9760101de', 'ostensibly', '/ɒˈstensəbli/', 'adverb', 'apparently, or according to what is stated, though perhaps not really', 'The trip was ostensibly for business, but he spent most of it on the beach.', array['apparently','seemingly','supposedly']::text[], array['genuinely','actually']::text[], 'C2', 'academic', null),
  ('d317b2a3-bfbe-551f-86c9-913bec2c41f4', 'paradigm', '/ˈpærədaɪm/', 'noun', 'a typical model or pattern; a set of ideas that shapes thinking in a field', 'The discovery caused a paradigm shift in physics.', array['model','pattern']::text[], array[]::text[], 'C2', 'science', null),
  ('f592e478-4875-5741-a25c-b5309794c65a', 'capricious', '/kəˈprɪʃəs/', 'adjective', 'changing suddenly and unexpectedly', 'The mountain weather is notoriously capricious.', array['unpredictable','changeable','volatile']::text[], array['stable','predictable']::text[], 'C2', 'environment', null),
  ('da52a438-d6f6-5559-95bc-b5edb14bc169', 'magnanimous', '/mæɡˈnænɪməs/', 'adjective', 'generous and kind, especially towards a rival or someone less powerful', 'She was magnanimous in victory and praised her opponent.', array['gracious','big-hearted']::text[], array['petty','vindictive']::text[], 'C2', 'daily', null),
  ('e266a36f-f13e-51e0-ac6f-90251a9c531c', 'ineffable', '/ɪnˈefəbl/', 'adjective', 'too great or extreme to be expressed in words', 'Standing at the summit, he felt an ineffable sense of peace.', array['indescribable','inexpressible']::text[], array['describable','expressible']::text[], 'C2', 'daily', null),
