  ('0405d88c-ab32-5c6b-8ed4-11debf266ace', 'anthropogenic', '/ˌænθrəpəˈdʒenɪk/', 'adjective', 'caused or produced by human activity', 'Most scientists agree that recent warming is largely anthropogenic.', array['human-made','man-made']::text[], array['natural']::text[], 'C2', 'environment', 'A precise term for environment essays; pair it with "emissions" or "climate change".'),
  ('5269c5fc-b878-5db7-80f8-ed6f653c0935', 'by the same token', '/baɪ ðə seɪm ˈtəʊkən/', 'idiom', 'for the same reason; in a similar way', 'Exercise improves your health; by the same token, a poor diet damages it.', array['similarly','likewise']::text[], array[]::text[], 'C2', 'idioms', null),
