  ('a6c1d4c4-0b7a-56ad-b42d-25f484443b20', 'stave off', '/steɪv ˈɒf/', 'phrasal verb', 'to stop something bad from happening for a period of time', 'The company cut costs to stave off bankruptcy.', array['avert','ward off']::text[], array[]::text[], 'C2', 'phrasal_verbs', null),
  ('5309b58d-1166-5ec7-8e0a-12af6c20aef4', 'cognizant', '/ˈkɒɡnɪzənt/', 'adjective', 'having knowledge or awareness of something', 'Policymakers must be cognizant of the risks involved.', array['aware','mindful']::text[], array['unaware','oblivious']::text[], 'C2', 'academic', null),
  ('0eaaf6d3-1491-5646-b354-84a3f1bf2082', 'nascent', '/ˈnæsnt/', 'adjective', 'just starting to develop', 'The country''s nascent tech industry is attracting investors.', array['emerging','budding']::text[], array['mature','established']::text[], 'C2', 'technology', null),
  ('b056eeb4-f49c-518b-b43b-08a10e28f916', 'vicarious', '/vɪˈkeəriəs/', 'adjective', 'experienced through the actions of another person rather than directly', 'She took vicarious pleasure in her daughter''s success.', array['indirect','second-hand']::text[], array['direct','first-hand']::text[], 'C2', 'daily', null),
  ('fcbc65e6-d40a-571f-be31-e3c3726ce7b7', 'intransigent', '/ɪnˈtrænsɪdʒənt/', 'adjective', 'refusing to change your opinion or behaviour', 'Talks broke down because both sides remained intransigent.', array['stubborn','uncompromising']::text[], array['flexible','accommodating']::text[], 'C2', 'business', null),
